package dev.bennett.codexmeter;
import java.time.*;import java.util.*;import org.json.*;

/** Deterministic synthetic fixtures. No auth/session/device data is accessed. */
public final class RpgStep2SelfTest {
    static int checks;static final long D=86400000L,W=7*D,S=LocalDate.parse("2026-09-01").atStartOfDay(LedgerAggregation.ZONE).toInstant().toEpochMilli(),NOW=S+40*D;
    static void check(boolean v,String label){checks++;if(!v)throw new AssertionError(label);}
    static long xp(JSONObject d)throws Exception{return RpgEngine.state(d).getLong("xp");}
    static LedgerRecord row(long at,double p,long reset){return new LedgerRecord("weekly","pro",at,p,Double.toString(p),reset,604800,"api_precise",false);}
    static void run(JSONObject doc,List<LedgerRecord> rows,long now)throws Exception {RpgEngine.reconcile(doc,rows,List.of(),List.of(),List.of(),now,true);}
    static JSONObject official(String account,long at,long lifetime,int days,long each)throws Exception {JSONArray b=new JSONArray();for(int i=0;i<days;i++)b.put(new JSONObject().put("startDate",LedgerAggregation.day(at).minusDays(i).toString()).put("tokens",each));return new JSONObject().put("account",account).put("source","codex_account_usage_v1").put("at",at).put("summary",new JSONObject().put("lifetimeTokens",lifetime)).put("dailyUsageBuckets",b);}
    static JSONObject breakdown(long input,long cached,long output)throws Exception {return new JSONObject().put("inputTokens",input).put("cachedInputTokens",cached).put("outputTokens",output).put("reasoningOutputTokens",0).put("totalTokens",input+output);}
    static JSONObject local(String account,String session,String turn,long at,long total)throws Exception {return new JSONObject().put("account",account).put("identity_verified",true).put("source","codex_thread_cumulative_v1").put("session",session).put("turn",turn).put("at",at).put("total",breakdown(total-10,0,10)).put("last",breakdown(40,20,10));}
    public static void main(String[] args)throws Exception {
        JSONObject d=AccountProgress.empty();run(d,List.of(row(S+1000,80,S+W)),NOW);check(xp(d)==0,"One quota snapshot is not a dated activity or fabricated XP");check(RpgEngine.summary(d).getString("token_status").equals("unknown"),"Unavailable tokens are unknown");check(RpgEngine.summary(d).isNull("token_total"),"Unknown is not zero tokens");
        List<LedgerRecord> rows=List.of(row(S+1000,0,S+W),row(S+2000,13,S+W));run(d,rows,NOW);long earned=xp(d);check(earned>0,"Verified old activity migrated");check(RpgEngine.summary(d).getInt("activity_days")==1,"Actual polling alone cannot award activity days");
        run(d,rows,NOW);check(xp(d)==earned,"Repeated migration has no duplicate XP");String stable=RpgEngine.state(d).toString();run(d,rows,NOW);check(stable.equals(RpgEngine.state(d).toString()),"Unchanged reconciliation reuses result");check(RpgEngine.state(d).getLong("pairs_last_update")==1,"Changed-day incremental calculation");
        String recommended=RpgEngine.state(d).getString("recommended_title");for(int i=0;i<10;i++){RpgEngine.summary(d);run(d,rows,NOW);}check(recommended.equals(RpgEngine.state(d).getString("recommended_title")),"Reading does not reshuffle title");
        check(RpgEngine.equip(d,recommended),"Unlocked title can be equipped");check(!RpgEngine.equip(d,"tokens_1000000000000"),"Locked title rejected");check(xp(d)==earned,"Equipping title has no XP effect");
        d=new JSONObject(d.toString());check(RpgEngine.state(d).getString("equipped_title").equals(recommended),"Equipped title survives serialized restart");
        run(d,List.of(row(S+1000,0,S+W),row(S+2000,13,S+W),row(S+3000,0,S+W+D)),NOW);check(xp(d)==earned,"Early/global reset does not manufacture activity XP");
        long before=xp(d);run(d,List.of(row(S+1000,0,S+W),row(S+2000,13,S+W),row(S+3000,0,S+W+D),row(S+4000,40,S+W+D)),NOW);check(xp(d)>=before,"Post-reset actual increase grows monotonically");
        List<LedgerRecord> gap=List.of(row(S+1000,0,S+W),row(S+D+1000,80,S+W));JSONObject no=AccountProgress.empty();run(no,gap,NOW);check(xp(no)==0,"Cross-midnight unassigned consumption earns no fabricated date");
        no=AccountProgress.empty();run(no,List.of(row(S+1000,0,S+W),row(S+4*D,80,S+W)),NOW);check(xp(no)==0,"Long observation gap does not create streak/activity");
        JSONObject a=AccountProgress.empty(),b=AccountProgress.empty();JSONObject response=official("A",NOW,100_000_000L,1,100_000_000L);
        check(RpgEngine.ingestOfficial(a,"A",response,NOW),"Actual-field official envelope accepted");long tx=xp(a);check(tx>0,"Token day and first milestones awarded");check(!RpgEngine.ingestOfficial(b,"B",response,NOW),"Account mismatch rejects token import");check(xp(b)==0,"Other account remains separate");
        RpgEngine.ingestOfficial(a,"A",response,NOW);check(xp(a)==tx,"Duplicate official snapshot has no duplicate reward");
        JSONObject local=local("A","session-1","turn-1",NOW,60_000_000L).put("prompt","DO_NOT_STORE");RpgEngine.ingestLocal(a,"A",local,NOW);check(RpgEngine.summary(a).getLong("token_total")==100_000_000L,"Account summary and local processed counter never add");check(!RpgEngine.state(a).toString().contains("DO_NOT_STORE"),"Prompt excluded by whitelist");check(xp(a)==tx,"Local overlapping cumulative counter has no daily re-award");
        JSONObject tokens=RpgTokens.empty();check(RpgTokens.local(tokens,"A",local,NOW),"Verified session metadata accepted");RpgTokens.local(tokens,"A",local,NOW);check(RpgTokens.localTotal(tokens)==60_000_000L,"Cumulative replay deduplicated");
        RpgTokens.local(tokens,"A",local("A","session-1","turn-2",NOW,70_000_000L),NOW);check(RpgTokens.localTotal(tokens)==70_000_000L,"Same session newer turn replaces high-water, not sums");
        check(tokens.getJSONObject("turns").length()==2,"Latest per-turn response stored separately");check(!RpgTokens.local(tokens,"A",local("A","fork","turn-1",NOW,70_000_000L).put("inherited_history",true),NOW),"Fork inherited counters rejected");
        check(!RpgTokens.local(tokens,"A",local("A","x","t",NOW,10).put("identity_verified",false),NOW),"Unattributed session rejected");
        boolean bad=false;try{RpgTokens.local(tokens,"A",local("A","x","t",NOW,10).put("total",breakdown(5,6,5)),NOW);}catch(IllegalArgumentException e){bad=true;}check(bad,"Cached input is a subset, not added tokens");
        JSONObject cumulative=AccountProgress.empty();RpgEngine.ingestOfficial(cumulative,"A",official("A",NOW,1_000_000_000L,0,0),NOW);check(RpgEngine.summary(cumulative).getInt("activity_days")==0,"Lifetime counter creates no invented activity dates");check(RpgEngine.eligibleTitles(cumulative).contains("tokens_1000000000"),"Lifetime-only verified milestone can unlock");check(RpgEngine.summary(cumulative).getInt("level")>1,"Historical token milestones do not restart at level 1");
        JSONObject lifetimeActivity=AccountProgress.empty();run(lifetimeActivity,List.of(row(NOW-2000,0,NOW+W),row(NOW-1000,13,NOW+W)),NOW);RpgEngine.ingestOfficial(lifetimeActivity,"A",official("A",NOW,1_000_000_000L,0,0),NOW);
        check(Math.abs(RpgEngine.state(lifetimeActivity).getJSONObject("KR").getDouble("latest_score")-RpgTier.score("KR",1,0,0,null,false))<.000001,"Lifetime-only history leaves daily intensity unavailable, not zero");
        JSONObject tierJournal=AccountProgress.empty();RpgEngine.ingestOfficial(tierJournal,"A",official("A",NOW,100_000_000L,1,100_000_000L),NOW);RpgTier.week(RpgEngine.state(tierJournal).getJSONObject("KR"),"weekly|pro|604800",NOW-W,20,true);
        JSONObject tierRestored=AccountProgress.empty();RpgEngine.merge(tierRestored,"A",RpgEngine.export(tierJournal,"A"),NOW);
        check(RpgEngine.state(tierRestored).getJSONObject("KR").getJSONObject("weeks").toString().equals(RpgEngine.state(tierJournal).getJSONObject("KR").getJSONObject("weeks").toString()),"Restored regional tier retains certified score history");
        check(RpgEngine.state(tierRestored).getJSONObject("KR").getString("policy").equals("weekly|pro|604800")&&RpgEngine.state(tierRestored).getJSONObject("KR").getJSONArray("evaluations").length()==RpgEngine.state(tierJournal).getJSONObject("KR").getJSONArray("evaluations").length(),"Restored tier retains policy and permanent evaluation audit");
        response=official("A",NOW+1,50_000_000L,1,50_000_000L);RpgEngine.ingestOfficial(a,"A",response,NOW+1);check(RpgEngine.summary(a).getLong("token_total")==100_000_000L&&xp(a)>=tx,"Server correction never retracts achievements/XP");
        check(RpgEngine.state(a).getJSONObject("KR").getInt("tier")<=4,"Insufficient valid weeks limits provisional placement");
        JSONObject journal=RpgEngine.export(a,"A"),restored=AccountProgress.empty();check(RpgEngine.merge(restored,"A",journal,NOW+1),"Account-bound journal restores old achievements and XP");long restoredXp=xp(restored);check(restoredXp==xp(a),"Restore uses award targets rather than adding account totals");RpgEngine.merge(restored,"A",journal,NOW+1);check(xp(restored)==restoredXp,"Repeated device merge cannot duplicate XP");check(RpgEngine.summary(restored).getLong("token_total")==100_000_000L,"Verified lifetime token scope restored");check(!RpgEngine.merge(restored,"B",journal,NOW+1),"Other-account journal rejected");
        JSONObject invalid=new JSONObject(journal.toString());invalid.getJSONObject("rpg").getJSONObject("awards").put("arbitrary-xp",9999999);String unchanged=restored.toString();bad=false;try{RpgEngine.merge(restored,"A",invalid,NOW+1);}catch(IllegalArgumentException e){bad=true;}check(bad&&unchanged.equals(restored.toString()),"Invalid journal leaves original untouched");
        Set<String> ids=new HashSet<>(),titles=new HashSet<>();for(RpgCatalog.Entry e:RpgCatalog.ALL){check(ids.add(e.id)&&titles.add(e.title),"Stable unique achievement/title "+e.id);check(!e.en.isEmpty()&&!e.titleEn.isEmpty()&&!e.descriptionKo().isEmpty()&&!e.descriptionEn().isEmpty(),"English metadata "+e.id);}
        check(RpgCatalog.ALL.size()==41&&titles.size()>=30,"41 distinct goals and titles");
        JSONObject archived=AccountProgress.empty();JSONObject closed=new JSONObject().put("id","weekly|pro|604800@"+(S+W)).put("start",S).put("end",S+W).put("used","80").put("observations",40).put("quality","near_boundary_observations_no_interpolation");AccountProgress.importLegacy(archived,"old-pro",new JSONObject().put("settlements",new JSONArray().put(closed)),null);run(archived,List.of(),NOW);check(RpgEngine.summary(archived).getInt("valid_weeks")==1&&RpgEngine.summary(archived).getInt("level")>1,"Pruned certified old week restores weekly XP");long archiveXp=xp(archived);run(archived,List.of(),NOW);check(xp(archived)==archiveXp,"Repeated archived settlement migration never doubles XP");check(RpgEngine.summary(archived).getInt("activity_days")==0,"Archived whole-week total does not invent daily activity");
        JSONObject localOld=RpgTokens.empty();RpgTokens.local(localOld,"A",local("A","s","t",NOW-1000,50),NOW);JSONObject localNew=RpgTokens.empty();RpgTokens.local(localNew,"A",local("A","s","t",NOW,60).put("last",breakdown(50,0,5)),NOW);RpgTokens.mergeJournal(localNew,localOld,"A",NOW);check(localNew.getJSONObject("turns").getJSONObject("s:t").getLong("at")==NOW,"Old journal cannot overwrite latest per-turn metadata");
        JSONObject high=AccountProgress.empty();RpgEngine.ingestOfficial(high,"A",official("A",NOW,1_000_000_000_000L,1,10),NOW);check(!RpgEngine.eligibleTitles(high).contains("tokens_1000000000000"),"Mythic token quantity alone cannot unlock without long-term activity");
        int lvl=1;for(long n=0;n<=1_000_000;n+=1000){int next=RpgEngine.level(n);check(next>=lvl&&RpgEngine.threshold(next)<=n&&RpgEngine.threshold(next+1)>n,"Monotone curve and thresholds");lvl=next;}check(RpgEngine.level(RpgEngine.threshold(150))==150,"Growth continues beyond level 100");check(RpgEngine.tokenXp(Long.MAX_VALUE)==75,"Extreme token reward capped");check(RpgEngine.quotaXp(10000)==25,"Quota bonus capped independently of reset counts");
        for(String region:new String[]{"KR","WORLD"}){
            JSONObject t=RpgTier.empty(region);RpgTier.current(t,98,S,true,true);int grade=t.getInt("tier");RpgTier.current(t,0,S+D,false,false);check(t.getInt("tier")==grade,"Reset/unchanged counter preserves "+region);
            RpgTier.week(t,"pro",S+W,0,true);RpgTier.week(t,"pro",S+2*W,0,true);check(t.getInt("tier")==grade,"Two-week promotion protection "+region);
            RpgTier.week(t,"pro",S+3*W,0,true);RpgTier.week(t,"pro",S+4*W,0,true);check(t.getInt("tier")==grade&&t.getBoolean("warning"),"Two lows only internal warning "+region);
            RpgTier.week(t,"pro",S+5*W,0,true);check(t.getInt("tier")==grade-1&&t.getInt("highest")==grade,"Three certified lows + long score demote one "+region);
            int held=t.getInt("tier");RpgTier.week(t,"pro",S+6*W,0,false);check(t.getInt("tier")==held,"Unverified week cannot demote "+region);RpgTier.week(t,"free",S+8*W,0,true);check(t.getInt("low_streak")==0&&t.getInt("highest")==grade,"Plan/gap breaks streak but preserves peak "+region);
        }
        JSONObject certified=AccountProgress.empty();JSONObject cs=RpgEngine.state(certified);for(String region:new String[]{"KR","WORLD"}){JSONObject t=cs.getJSONObject(region);RpgTier.current(t,98,S-10*W,true,true);t.put("end",S).put("policy","weekly|pro|604800");t.getJSONObject("weeks").put(Long.toString(S),0);}
        for(int i=-4;i<=4;i++)cs.getJSONObject("weeks").put(Long.toString(S+i*W),new JSONObject().put("start",S+(i-1)*W).put("end",S+i*W).put("policy","weekly|pro|604800").put("used","0"));
        Map<LocalDate,Long> calendar=new HashMap<>();for(LocalDate date=LedgerAggregation.day(S-30*D);date.isBefore(LedgerAggregation.day(S+5*W));date=date.plusDays(1))calendar.put(date,0L);
        check(!RpgEngine.evaluateCertifiedWindow(certified,"weekly|pro|604800",S+W,calendar,false,true,NOW),"Local partial scope cannot certify account-wide low activity");
        Map<LocalDate,Long> incomplete=new HashMap<>(calendar);incomplete.remove(LedgerAggregation.day(S+W).minusDays(1));check(!RpgEngine.evaluateCertifiedWindow(certified,"weekly|pro|604800",S+W,incomplete,true,true,NOW),"Missing token day is not zero in demotion engine");
        for(int i=1;i<=3;i++)check(RpgEngine.evaluateCertifiedWindow(certified,"weekly|pro|604800",S+i*W,calendar,true,true,NOW),"Complete synthetic calendar admits certified evaluation");
        check(cs.getJSONObject("KR").getInt("tier")==8&&cs.getJSONObject("WORLD").getInt("tier")==8,"Engine integration demotes both at most one with three verified lows");
        double kr=RpgTier.score("KR",20,4,100_000_000L,50d,true),world=RpgTier.score("WORLD",20,4,100_000_000L,50d,true);check(kr!=world,"Independent regional benchmarks");check(AccountTier.rank(RpgTier.score("KR",30,8,3_000_000_000L,100d,true))==AccountTier.rank(RpgTier.score("WORLD",30,8,3_000_000_000L,100d,true)),"World is not always one rank above");
        for(int days:new int[]{7,20,30})for(long rate:new long[]{100_000L,10_000_000L,100_000_000L})for(String region:new String[]{"KR","WORLD"})System.out.printf(java.util.Locale.ROOT,"Simulation %s active=%d token/day=%d score=%.2f tier=%d%n",region,days,rate,RpgTier.score(region,days,4,days*rate,50d,true),AccountTier.rank(RpgTier.score(region,days,4,days*rate,50d,true)));
        for(int daily:new int[]{35,80,120})for(int years:new int[]{1,3,10})System.out.println("XP curve daily="+daily+" years="+years+" level="+RpgEngine.level((long)daily*365*years+50L*52*years));
        JSONObject large=AccountProgress.empty();List<LedgerRecord> many=new ArrayList<>();for(int day=0;day<30;day++){long reset=S+(day/7+1)*W;for(int i=0;i<100;i++)many.add(row(S+day*D+i*1000,Math.min(99,(day%7)*10+i*.05),reset));}
        run(large,many,NOW);JSONObject view=RpgEngine.summary(large);check(view.toString().length()<3000,"Compact home cache bound");long start=System.nanoTime();for(int i=0;i<10000;i++)RpgEngine.summary(large);long ms=(System.nanoTime()-start)/1_000_000;check(ms<5000,"Summary does not rescan historical ledger");System.out.println("Home summary 10,000 reads: "+ms+" ms; "+view.toString().length()+" chars; synthetic JVM");
        System.out.println("RPG Step 2: "+checks+" assertions passed (synthetic engine; no phone recovery proof).");
    }
}
